import sys

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        return

    s1 = lines[0]
    s2 = lines[1]

    len1 = len(s1)
    len2 = len(s2)

    if len1 >= len2:
        result = s1[:len2] + s2
    else:
        result = s1 + s2[:len1]

    print(result)

if __name__ == "__main__":
    main()
